import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";

const ReviewForm = () => {
  const location = useLocation();
  const freelancerId = location.state?.freelancerId;
  const navigate = useNavigate();

  const [freelancerAddress, setFreelancerAddress] = useState("");
  const [comment, setComment] = useState("");
  const [rating, setRating] = useState(5);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchWallet = async () => {
      if (!freelancerId) {
        setError("Freelancer ID not provided.");
        return;
      }

      try {
        const res = await fetch(`http://localhost:5001/api/wallet/${freelancerId}`, {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        });

        const data = await res.json();
        if (res.ok && data.walletAddress) {
          setFreelancerAddress(data.walletAddress);
        } else {
          setError(data.message || "Could not fetch wallet address.");
        }
      } catch (err) {
        console.error("Failed to fetch wallet address:", err);
        setError("Something went wrong.");
      }
    };

    fetchWallet();
  }, [freelancerId]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!freelancerAddress) {
      setError("Freelancer wallet address not found.");
      return;
    }

    try {
      setLoading(true);
      const res = await fetch("http://localhost:5001/api/reviews/add", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ freelancerAddress, comment, rating }),
      });

      const data = await res.json();
      if (data.success) {
        setSubmitted(true);
        setComment("");
        setRating(5);
      } else {
        setError(data.message || "Failed to submit review.");
      }
    } catch (err) {
      console.error("Error submitting review:", err);
      setError("Submission failed.");
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return <p className="text-green-600">✅ Review submitted!</p>;
  }

  return (
    <form onSubmit={handleSubmit}>
      <h2>Leave a Review</h2>
      <textarea
        placeholder="Write your review..."
        value={comment}
        onChange={(e) => setComment(e.target.value)}
        required
      />
      <select value={rating} onChange={(e) => setRating(Number(e.target.value))}>
        {[5, 4, 3, 2, 1].map((r) => (
          <option key={r} value={r}>{r} ⭐</option>
        ))}
      </select>
      {error && <p style={{ color: "red" }}>{error}</p>}
      <button type="submit" disabled={loading}>
        {loading ? "Submitting..." : "Submit Review"}
      </button>
    </form>
  );
};

export default ReviewForm;
